import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Laravel Multi-Tenant App Architecture","description":"How a request flows through the kits: modules, central vs tenant context, middleware, Data objects, services, repositories and shared Inertia props.","frontmatter":{"title":"Laravel Multi-Tenant App Architecture","description":"How a request flows through the kits: modules, central vs tenant context, middleware, Data objects, services, repositories and shared Inertia props.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/core/architecture.html"}],["meta",{"property":"og:title","content":"Laravel Multi-Tenant App Architecture"}],["meta",{"property":"og:description","content":"How a request flows through the kits: modules, central vs tenant context, middleware, Data objects, services, repositories and shared Inertia props."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/core/architecture.html"}],["meta",{"name":"twitter:title","content":"Laravel Multi-Tenant App Architecture"}],["meta",{"name":"twitter:description","content":"How a request flows through the kits: modules, central vs tenant context, middleware, Data objects, services, repositories and shared Inertia props."}]]},"headers":[],"relativePath":"docs/core/architecture.md","filePath":"docs/core/architecture.md","lastUpdated":1790486087000}'),n={name:"docs/core/architecture.md"};function o(r,e,i,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>All three kits share one Laravel backend. The frontend is an Inertia v3 single-page app; there is no separate API.</p><p>A request takes this path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request</span></span>
<span class="line"><span>  → Tenancy check (central or tenant context, decided by host)</span></span>
<span class="line"><span>  → web middleware (locale, shared props, tenant status checks)</span></span>
<span class="line"><span>  → Module route</span></span>
<span class="line"><span>  → Controller → Data object → Service → Model / Repository</span></span>
<span class="line"><span>  → Inertia page, or redirect with a toast</span></span></code></pre></div><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><p>Every feature lives in its own module under <code>Modules/&lt;Module&gt;/</code> (PSR-4 namespace <code>Modules\\</code>). A module owns its routes, controllers, Data objects, services and enums, and registers them through its service provider.</p><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>Auth</code></td><td>Fortify actions, Inertia auth views, rate limiters</td></tr><tr><td><code>Dashboard</code></td><td>Landing page (<code>/</code>) and <code>/dashboard</code></td></tr><tr><td><code>Menu</code></td><td>Database-driven navigation, reorder and reset</td></tr><tr><td><code>RolePermission</code></td><td>Roles CRUD, <code>RoleEnum</code>, <code>PermissionService</code></td></tr><tr><td><code>Settings</code></td><td>Profile, security, language, appearance and layout settings, <code>SetUserLocale</code> middleware</td></tr><tr><td><code>Tenant</code></td><td>Tenants, domains, auth features per domain, maintenance, suspension, tenant invitations</td></tr><tr><td><code>User</code></td><td>Users CRUD, per-user permissions, user invitations</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Add routes in a module</p><p><code>routes/web.php</code> is intentionally empty. Each module&#39;s service provider (registered in <code>bootstrap/providers.php</code>) loads the module&#39;s own <code>routes/web.php</code>.</p></div><p>See <a href="/docs/getting-started/project-structure.html#inside-a-module">Project structure → Inside a module</a> for the folder layout.</p><h2 id="layered-code" tabindex="-1">Layered code <a class="header-anchor" href="#layered-code" aria-label="Permalink to &quot;Layered code&quot;">​</a></h2><p>Each layer has one job, so controllers stay small and business logic can be reused and tested on its own.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Controller   → receives validated input → calls a service → returns Inertia page or redirect</span></span>
<span class="line"><span>Data object  → validation rules + typed input (+ generated TypeScript type)</span></span>
<span class="line"><span>Service      → business logic, transactions</span></span>
<span class="line"><span>Repository   → complex queries (only where needed)</span></span></code></pre></div><ul><li><strong>Data objects</strong> use <code>spatie/laravel-data</code>. Their <code>rules()</code>, <code>attributes()</code> and <code>messages()</code> are translated, and classes marked <code>#[TypeScript]</code> are exported to the frontend.</li><li><strong>Toasts</strong>: after a successful action the controller flashes a <code>toast</code> with <code>Inertia::flash()</code>. The frontend listens for it and shows it with the kit&#39;s toast library.</li></ul><details class="details custom-block"><summary>View implementation example</summary><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Modules/Tenant/Http/Controllers/TenantController.php</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> store</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TenantRegisterData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $data)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> RedirectResponse</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    $this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tenantService</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createTenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($data);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Inertia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;toast&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;success&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;message&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> __</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;modules/tenant.toasts.created&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> to_route</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tenants.index&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></details><p><strong>Examples in the kit</strong></p><table tabindex="0"><thead><tr><th>Layer</th><th>Classes</th></tr></thead><tbody><tr><td>Services</td><td><code>TenantService</code>, <code>DomainService</code>, <code>UserService</code>, <code>PermissionService</code>, <code>MenuService</code>, <code>LayoutService</code>, ...</td></tr><tr><td>Repositories</td><td><code>TenantRepository</code>, <code>DomainRepository</code></td></tr><tr><td>Data objects</td><td><code>TenantRegisterData</code>, <code>DomainData</code>, <code>UserData</code>, <code>MaintenanceModeData</code>, ...</td></tr></tbody></table><h2 id="central-vs-tenant-context" tabindex="-1">Central vs tenant context <a class="header-anchor" href="#central-vs-tenant-context" aria-label="Permalink to &quot;Central vs tenant context&quot;">​</a></h2><p>One codebase serves two contexts. The <strong>host name</strong> decides which one a request runs in, and that choice switches the database, the auth guard and the defaults for permissions and menus.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Request host</span></span>
<span class="line"><span>  ├─ APP_DOMAIN (vue.test)            → central context</span></span>
<span class="line"><span>  └─ any other host (acme.vue.test)   → look up in the domains table</span></span>
<span class="line"><span>        ├─ found                      → tenant context</span></span>
<span class="line"><span>        └─ not found                  → 404</span></span></code></pre></div><table tabindex="0"><thead><tr><th></th><th>Central</th><th>Tenant</th></tr></thead><tbody><tr><td>Host</td><td><code>APP_DOMAIN</code> (e.g. <code>vue.test</code>)</td><td>Any other host, e.g. <code>acme.vue.test</code></td></tr><tr><td>Database</td><td><code>DB_DATABASE</code></td><td><code>tenant&lt;id&gt;</code></td></tr><tr><td>Auth guard</td><td><code>web</code></td><td><code>tenant</code></td></tr><tr><td>User provider / broker</td><td><code>central_users</code></td><td><code>tenant_users</code></td></tr><tr><td>Permissions config</td><td><code>config/permissions/*.php</code></td><td><code>config/permissions/tenant/*.php</code></td></tr><tr><td>Menus seeder</td><td><code>Database\\Seeders\\MenuSeeder</code></td><td><code>Database\\Seeders\\tenant\\MenuSeeder</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">How the context is chosen</p><p><code>InitializeTenancyIfTenantDomain</code> is prepended to the <strong>global</strong> middleware stack, so it runs before everything else. On the central domain it forces the <code>web</code> guard and <code>central_users</code> broker and leaves tenancy off. On any other host it hands over to stancl&#39;s <code>InitializeTenancyByDomain</code>.</p></div><h3 id="when-tenancy-starts" tabindex="-1">When tenancy starts <a class="header-anchor" href="#when-tenancy-starts" aria-label="Permalink to &quot;When tenancy starts&quot;">​</a></h3><p>The <code>TenancyInitialized</code> event runs these listeners in order. <code>TenancyEnded</code> runs the matching revert listeners.</p><table tabindex="0"><thead><tr><th>Listener</th><th>Effect</th></tr></thead><tbody><tr><td><code>BootstrapTenancy</code></td><td>Switches database, cache, filesystem and queue context</td></tr><tr><td><code>ConfigureTenantAuth</code></td><td>Switches Laravel and Fortify to the <code>tenant</code> guard and <code>tenant_users</code> broker</td></tr><tr><td><code>ApplyTenantFortifyFeatures</code></td><td>Applies the domain&#39;s enabled auth features</td></tr><tr><td><code>ApplyTenantAppName</code></td><td>Sets <code>app.name</code> to the domain&#39;s App name, else the tenant company</td></tr></tbody></table><h3 id="routes-in-each-context" tabindex="-1">Routes in each context <a class="header-anchor" href="#routes-in-each-context" aria-label="Permalink to &quot;Routes in each context&quot;">​</a></h3><p>Modules register their routes once, so most pages (users, roles, menus, settings, dashboard) work in both contexts.</p><table tabindex="0"><thead><tr><th>Route should work on</th><th>Add middleware</th></tr></thead><tbody><tr><td>Both (default)</td><td>nothing extra</td></tr><tr><td>Central domain only</td><td><code>central.only</code> (<code>PreventAccessFromTenantDomains</code>)</td></tr><tr><td>Tenant domains only</td><td>stancl&#39;s <code>PreventAccessFromCentralDomains</code></td></tr></tbody></table><p><strong>Related files</strong></p><ul><li><code>app/Http/Middleware/InitializeTenancyIfTenantDomain.php</code></li><li><code>app/Providers/TenancyServiceProvider.php</code> (event → listener map)</li><li><code>app/Listeners/</code> (<code>ConfigureTenantAuth</code>, <code>RevertTenantAuth</code>, <code>ApplyTenantAppName</code>, <code>RestoreCentralAppName</code>)</li><li><code>Modules/Tenant/Listeners/</code> (<code>ApplyTenantFortifyFeatures</code>, <code>RestoreCentralFortifyFeatures</code>)</li></ul><p>More: <a href="/docs/core/multi-tenancy.html">Multi-tenancy</a>.</p><h2 id="web-middleware" tabindex="-1">Web middleware <a class="header-anchor" href="#web-middleware" aria-label="Permalink to &quot;Web middleware&quot;">​</a></h2><p><code>bootstrap/app.php</code> appends these to the <code>web</code> group, in this order:</p><table tabindex="0"><thead><tr><th>Middleware</th><th>Purpose</th></tr></thead><tbody><tr><td><code>HandleAppearance</code></td><td>Shares the <code>appearance</code> cookie with the Blade root view</td></tr><tr><td><code>SetUserLocale</code></td><td>Resolves the locale (user → domain → app default)</td></tr><tr><td><code>HandleInertiaRequests</code></td><td>Shared props (below)</td></tr><tr><td><code>AddLinkHeadersForPreloadedAssets</code></td><td>Laravel&#39;s preload <code>Link</code> headers for Vite assets</td></tr><tr><td><code>EnsureTenantAuthFeatureEnabled</code></td><td>404 for auth routes disabled on this domain</td></tr><tr><td><code>EnsureTenantIsNotSuspended</code></td><td>Renders <code>auth/Suspended</code> (403) for suspended tenants</td></tr><tr><td><code>EnsureTenantIsNotInMaintenance</code></td><td>Renders <code>auth/Maintenance</code> (503) during tenant maintenance</td></tr></tbody></table><p>Middleware aliases:</p><table tabindex="0"><thead><tr><th>Alias</th><th>Class</th><th>Note</th></tr></thead><tbody><tr><td><code>auth</code></td><td><code>TenancyAwareAuthenticate</code></td><td>Maps the <code>web</code> guard to <code>tenant</code> inside a tenant</td></tr><tr><td><code>guest</code></td><td><code>TenancyAwareRedirectIfAuthenticated</code></td><td>Same mapping</td></tr><tr><td><code>central.only</code></td><td><code>PreventAccessFromTenantDomains</code></td><td></td></tr><tr><td><code>permission</code>, <code>role</code></td><td>spatie middleware</td><td></td></tr></tbody></table><h2 id="shared-inertia-props" tabindex="-1">Shared Inertia props <a class="header-anchor" href="#shared-inertia-props" aria-label="Permalink to &quot;Shared Inertia props&quot;">​</a></h2><p><code>HandleInertiaRequests::share()</code> sends these props with every page:</p><table tabindex="0"><thead><tr><th>Prop</th><th>Content</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>app.name</code> (per-domain App name or tenant company on tenant domains)</td></tr><tr><td><code>appUrl</code>, <code>domain</code></td><td><code>app.url</code>, <code>tenancy.domain</code></td></tr><tr><td><code>auth.user</code></td><td>Current user</td></tr><tr><td><code>auth.isTenant</code></td><td><code>true</code> on tenant domains</td></tr><tr><td><code>auth.permissions</code></td><td>All permission names of the user</td></tr><tr><td><code>auth.isSuperAdmin</code></td><td>User has the <code>super-admin</code> role</td></tr><tr><td><code>locale</code>, <code>userLocale</code>, <code>defaultLocale</code>, <code>languages</code></td><td>Localization state</td></tr><tr><td><code>sidebarOpen</code></td><td>From the <code>sidebar_state</code> cookie</td></tr><tr><td><code>menus</code>, <code>setupMenus</code></td><td>Permission-filtered navigation trees</td></tr><tr><td><code>layout</code></td><td>Active layout settings</td></tr><tr><td><code>permissionsConfig</code></td><td>Grouped permissions from <code>config/permissions</code></td></tr><tr><td><code>lang</code></td><td>Translations (shared by <code>erag/laravel-lang-sync-inertia</code>)</td></tr></tbody></table><h2 id="error-pages" tabindex="-1">Error pages <a class="header-anchor" href="#error-pages" aria-label="Permalink to &quot;Error pages&quot;">​</a></h2><p><code>bootstrap/app.php</code> renders error responses as the Inertia page <code>errors/Error</code> (<code>errors/error</code> in React) with a <code>status</code> prop.</p><table tabindex="0"><thead><tr><th>Environment</th><th>Rendered as Inertia page</th></tr></thead><tbody><tr><td><code>local</code>, <code>testing</code></td><td>403 only (you still see Laravel&#39;s debug pages for other errors)</td></tr><tr><td>Other</td><td>403, 404, 500, 503</td></tr></tbody></table><p>A <code>TenantCouldNotBeIdentifiedException</code> (unknown host) becomes a 404.</p><h2 id="typed-frontend" tabindex="-1">Typed frontend <a class="header-anchor" href="#typed-frontend" aria-label="Permalink to &quot;Typed frontend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Generates</th><th>Import from</th></tr></thead><tbody><tr><td>Wayfinder</td><td>Typed route and controller functions in <code>resources/js/routes</code> and <code>resources/js/actions</code></td><td><code>@/routes/...</code>, <code>@/actions/...</code></td></tr><tr><td>TypeScript transformer</td><td>Data and enum types in <code>resources/js/types/Modules/...</code></td><td><code>@/types/Modules/...</code></td></tr></tbody></table><p>Regenerate both after backend changes; see <a href="/docs/getting-started/local-development.html#generated-files">Local development</a>.</p>`,45)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
